  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 840px;
}

th {
  text-align: left;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  padding: 12px 8px;
  border-bottom: 1px solid var(--border);
}

td {
  padding: 14px 8px;
  border-bottom: 1px solid rgba(29, 27, 23, 0.08);
  font-size: 0.92rem;
}

tr:hover {
  background: rgba(19, 111, 99, 0.06);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  padding: 4px 10px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.badge.in-stock {
  background: rgba(19, 111, 99, 0.16);
  color: var(--accent-strong);
}

.badge.low-stock {
  background: rgba(217, 119, 50, 0.2);
  color: #9a4f1d;
}

.badge.backorder {
  background: rgba(17, 24, 39, 0.16);
  color: #111827;
}

.badge.discontinued {
  background: rgba(148, 163, 184, 0.25);
  color: #475569;
}

