  align-items: center;
  gap: 6px;
  font-weight: 600;
  color: var(--ink);
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--accent);
}

.status.paused .status-dot {
  background: var(--accent-warm);
}

.status.archived .status-dot {
  background: #94a3b8;
}

@keyframes riseIn {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
